# raz: «в N раз / раза» с учётом числа; дробное значение — всегда «раза».
# fx: число рядом с порогом — не меньше 4 значащих цифр, но столько, чтобы
# округление не показало ровно порог, когда значение от него отличается
# (иначе «50 В» соседствовало бы со статусом «не выполняется»).
RAZ_JS = r'''
function fx(x,lim){for(var p=4;p<=12;p++){if(x===lim||Number(x.toPrecision(p))!==lim)return fmt(x,p);}return fmt(x,12);}
function raz(x){var s=fmt(x,3);if(s==='1'&&x!==1)s=fx(x,1);if(/[,·]/.test(s))return s+' раза';var n=Math.abs(Math.round(x))%100,m=n%10;return s+((m>=2&&m<=4&&(n<12||n>14))?' раза':' раз');}
'''

