js=RAZ_JS + r'''
function ge(a,b){return a>=b*(1-1e-12);}
function le(a,b){return a<=b*(1+1e-12);}
function sync(){var s=S('prof')==='strip';hideF('b',!s);hideF('d',s);}
function init(){$('prof').addEventListener('change',sync);sync();}
function calc(){
var strip=S('prof')==='strip',rho=P('rho'),sz=P(strip?'b':'d'),L=P('l'),t=P('t'),rt=P('rt');
if([rho,sz,L,t,rt].some(isNaN))return err('Заполните ρ, размер проводника, длину, глубину и цель проекта.');
if(rho<=0||sz<=0||L<=0||t<=0||rt<=0)return err('Все значения должны быть больше нуля.');
var d=strip?sz/2:sz;
if(!ge(d,5)||!le(d,30))return err(strip?'Ширина полосы вне проверенной области 10–60 мм.':'Диаметр вне проверенной области 5–30 мм.');
if(!ge(t,0.3)||!le(t,2))return err('Глубина укладки вне проверенной области 0,3–2 м.');
if(!ge(L,5*t))return err('Длина меньше 5·t = '+fmt(5*t,4)+' м. У короткого проводника формула перестаёт давать запас: при L = 2·t она занижает сопротивление примерно на 2 %, при L = 1,5·t — до 8 %. Оценка не выдаётся.');
if(!le(L,100))return err('Длина больше 100 м — вне проверенной численно области.');
var R=rho/(2*Math.PI*L)*Math.log(L*L/(d/1000*t));
if(!isFinite(R))return err('Значения вне диапазона надёжного расчёта.');
var worst=S('rhosrc')==='worst',ok=le(R,rt),cmp,st,n;
if(worst){cmp=ok?'не выше заданной цели':'выше заданной цели';st='Оценка, требуется измерение';}
else{cmp=ok?'не выше цели при этом ρ, но в сухой или морозный сезон ρ выше':'выше заданной цели уже при этом ρ';st=ok?'Недостаточно данных: ρ без сезонной поправки':'Оценка, требуется измерение';}
n='По численной проверке для однородного грунта формула завышает сопротивление на 3,3–8,5 % во всей области, которую пропускает калькулятор, то есть оценка с запасом. ';
if(strip)n+='У полосы толщиной 3–5 мм эквивалентный диаметр по двумерному расчёту 0,6–0,64·b, а не 0,5·b, поэтому запас ещё больше. ';
if(!worst)n+=ok?(rt/R<=1+1e-9?'ρ без сезонной поправки, а оценка уже на уровне цели: любой сезонный рост ρ её превысит. ':'ρ без сезонной поправки: до цели ρ может вырасти в '+raz(rt/R)+'. ')+'По Schneider Electric на глубине около 1 м сопротивление заземлителя в умеренном климате меняется в 1–3 раза между влажной зимой и сухим летом, а промерзание повышает ρ на порядки. ':'Даже без сезонной поправки оценка выше цели. ';
n+='Слоистость грунта, соседние электроды и соединения не учитываются — готовый заземлитель измеряют.';
out(row('Эквивалентный диаметр d',fmt(d,4)+' мм'+(strip?' (0,5·b)':''))+
row('Оценочное сопротивление R = ρ/(2πL)·ln(L²/(d·t))',fmt(R,4)+' Ом')+
row('Погрешность формулы (однородный грунт)','завышает R на 3,3–8,5 %')+
row('Сравнение с целью',fx(R,rt)+' Ом — '+cmp)+
row('Статус',st)+
note(n));
}
''',
about="""<div class="formula">R = ρ / (2π·L) · ln(L² / (d·t))&nbsp;&nbsp;&nbsp;полоса: d = 0,5·b, то есть R = ρ / (2π·L) · ln(2·L² / (b·t))</div>
<p>ρ — удельное сопротивление грунта, Ом·м; L — длина проводника, м; d — его диаметр, м; t — глубина укладки, м. Та же формула в десятичных логарифмах — 0,366·ρ/L·lg(L²/(d·t)) — приведена в методике расчёта заземления «ВОЛЬТ-СПБ» со ссылкой на справочник под редакцией Ю. Г. Барыбина, с условием, что длина электрода значительно больше глубины заложения. Для полосы в той же методике — lg(2·L²/(b·t)): ширина b заменяет диаметр с коэффициентом 0,5.</p>
<p><b>Откуда берётся формула и в какую сторону она ошибается.</b> Это потенциал в середине проводника с равномерно распределённым током плюс вклад его зеркального изображения в поверхности земли. В середине потенциал наибольший, поэтому у длинного проводника формула завышает сопротивление. У короткого, длина которого сравнима с глубиной, приближение для изображения перестаёт работать, и формула начинает занижать R. Проверка калькулятора — численный расчёт методом моментов с точным ядром трубчатого проводника и зеркальным изображением в однородном полупространстве; сам метод сверен с независимым расчётом, который воспроизводит точные решения для сферы и вытянутого сфероида. Проводник диаметром 5–30 мм, глубина 0,3–2 м:</p>
<table class="t"><tr><th>Длина L</th><th>Формула относительно численного расчёта</th></tr>
<tr><td>1,5·t</td><td>от −8,0 до −4,1 %</td></tr>
<tr><td>2·t</td><td>от −2,1 до −1,5 %</td></tr>
<tr><td>3·t</td><td>от +1,2 до +3,3 %</td></tr>
<tr><td>4·t</td><td>от +2,6 до +5,7 %</td></tr>
<tr><td>от 5·t до 100 м</td><td>от +3,3 до +8,5 %</td></tr></table>
<p>Поэтому калькулятор принимает только L ≥ 5·t — там формула везде с запасом, — длину до 100 м, глубину 0,3–2 м и диаметр 5–30 мм, то есть полосу шириной 10–60 мм. У полосы с реальной толщиной 3–5 мм эквивалентный диаметр по двумерному расчёту 0,6–0,64·b, а не 0,5·b, так что запас ещё больше: для полосы 40×4 мм длиной 10 м на глубине 0,7 м — около 9 %. На некоторых сайтах для полосы встречается запись ln(L²/(b·t)) — без множителя 2, то есть с d = b. Она даёт меньшее сопротивление; калькулятор использует более осторожную запись справочника.</p>
<p><b>Чем отличается от соседних расчётов.</b> Для замкнутого контура вокруг дома — <a href="kolcevoy-zazemlitel.html">кольцевой заземлитель</a> с оценкой R ≈ 2ρ/L, для стержней — <a href="vertikalnyy-zazemlitel.html">одиночный вертикальный электрод</a> и <a href="raschet-zazemleniya.html">несколько стержней</a>. Полосу, соединяющую стержни, нельзя просто включить параллельно им: поля растекания перекрываются. Ориентировочные значения ρ для разных грунтов — на странице кольцевого заземлителя.</p>
<p><b>Сезон и цель.</b> ρ меняется в течение года: по Schneider Electric на глубине около 1 м сопротивление заземлителя в умеренном климате меняется в 1–3 раза между влажной зимой и сухим летом, а промерзание повышает ρ на порядки. МЭК 60364-5-54 требует выбирать тип и глубину заложения заземлителя так, чтобы высыхание и промерзание грунта не увеличивали сопротивление выше требуемого. Поэтому по ρ без сезонной поправки калькулятор не сравнивает оценку с целью окончательно, а показывает, во сколько раз ρ может вырасти до цели. Если оценка выше цели уже при таком ρ, вывод от сезона не зависит: в сухой или морозный период сопротивление только больше. Требуемое значение задаёт проект по системе заземления и защите — например, условие <a href="zazemlenie-tt-uzo.html">RA·IΔn ≤ 50 В в системе TT</a>.</p>""",
example="""<p>Стальная полоса 40×4 мм длиной 10 м в траншее глубиной 0,7 м, ρ = 100 Ом·м. Для полосы d = 0,5 · 40 = 20 мм; L²/(d·t) = 100 / (0,02 · 0,7) ≈ 7143, ln 7143 ≈ 8,874; R ≈ 100 / (2π · 10) · 8,874 ≈ <b>14,12 Ом</b>. Численный расчёт для проводника диаметром 20 мм даёт 13,22 Ом, для полосы 40×4 с её реальным эквивалентным диаметром — 12,94 Ом: формула с запасом.</p>
<p>Пруток диаметром 10 мм длиной 20 м на глубине 0,5 м: R ≈ 100 / (2π · 20) · ln(400 / (0,01 · 0,5)) ≈ 0,7958 · 11,29 ≈ <b>8,98 Ом</b>, численный расчёт — 8,47 Ом. Отрезок той же полосы длиной 2 м на глубине 0,7 м калькулятор не считает: L меньше 5·t = 3,5 м.</p>""",
