js=RAZ_JS + r'''
function ge(a,b){return a>=b*(1-1e-12);}
function le(a,b){return a<=b*(1+1e-12);}
function sync(){var r=S('prof')==='round';hideF('d',!r);hideF('b',r);}
function init(){$('prof').addEventListener('change',sync);sync();}
function calc(){
var pr=S('prof'),rho=P('rho'),sz=P(pr==='round'?'d':'b'),L=P('l'),t0=P('t0'),rt=P('rt');
if([rho,sz,L,t0,rt].some(isNaN))return err('Заполните ρ, размер электрода, длину, заглубление и цель проекта.');
if(rho<=0||sz<=0||L<=0||rt<=0)return err('ρ, размер, длина и цель должны быть больше нуля.');
if(t0<0)return err('Заглубление верхнего конца не может быть отрицательным.');
var k=pr==='angle'?0.95:(pr==='strip'?0.5:1),d=k*sz;
if(!ge(d,8)||!le(d,60))return err('Эквивалентный диаметр d = '+fmt(d,6)+' мм вне проверенной области 8–60 мм.');
if(!ge(L,1)||!le(L,10))return err('Длина электрода вне проверенной области 1–10 м.');
if(!le(t0,2))return err('Заглубление верхнего конца больше 2 м — вне проверенной численно области.');
var dm=d/1000,T=t0+L/2,c=rho/(2*Math.PI*L),R=c*(Math.log(2*L/dm)+0.5*Math.log((4*T+L)/(4*T-L)));
if(!isFinite(R))return err('Значения вне диапазона надёжного расчёта.');
var h=row('Эквивалентный диаметр d',fmt(d,4)+' мм'+(pr==='angle'?' (0,95·b)':(pr==='strip'?' (0,5·b)':'')))+
row('Глубина середины электрода T = t₀ + L/2',fmt(T,4)+' м')+
row('Оценочное сопротивление R',fmt(R,4)+' Ом');
if(t0===0){var Rd=c*(Math.log(8*L/dm)-1);
 h+=row('По формуле Дуайта для стержня от поверхности (BS 7430)',fmt(Rd,4)+' Ом')+row('Расхождение двух формул',fmt(100*(R/Rd-1),3)+' %');}
h+=row('Для сравнения: грубая оценка ρ/L',fmt(rho/L,4)+' Ом')+
row('Погрешность формулы (однородный грунт)','завышает R на 2,4–11,7 %'+(t0===0?'; формула Дуайта — на 0,4–2,2 %':''));
var worst=S('rhosrc')==='worst',ok=le(R,rt),cmp,st,n;
if(worst){cmp=ok?'не выше заданной цели':'выше заданной цели';st='Оценка, требуется измерение';}
else{cmp=ok?'не выше цели при этом ρ, но в сухой или морозный сезон ρ выше':'выше заданной цели уже при этом ρ';st=ok?'Недостаточно данных: ρ без сезонной поправки':'Оценка, требуется измерение';}
n='По численной проверке для однородного грунта формула завышает сопротивление на 2,4–11,7 % во всей области, которую пропускает калькулятор, — сильнее у коротких толстых и глубоко заглублённых электродов. ';
if(t0===0)n+='Для стержня от поверхности формула Дуайта точнее — она завышает R лишь на 0,4–2,2 %; для сравнения с целью взята более осторожная формула с заглублением. ';
if(pr==='angle')n+='Коэффициент 0,95 проверен двумерным расчётом: для уголков 40–75 мм с полкой 4–6 мм получено 0,93–0,946·b, это меняет R меньше чем на 0,5 %. ';
if(pr==='strip')n+='У полосы толщиной 3–5 мм эквивалентный диаметр 0,6–0,64·b, так что 0,5·b даёт дополнительный запас. ';
if(!worst)n+=ok?(rt/R<=1+1e-9?'ρ без сезонной поправки, а оценка уже на уровне цели: любой сезонный рост ρ её превысит. ':'ρ без сезонной поправки: до цели ρ может вырасти в '+raz(rt/R)+'. ')+'По Schneider Electric на глубине около 1 м сопротивление заземлителя в умеренном климате меняется в 1–3 раза между влажной зимой и сухим летом, а промерзание повышает ρ на порядки. ':'Даже без сезонной поправки оценка выше цели. ';
n+='Сопротивление группы электродов больше, чем R одного, делённое на их число: поля растекания перекрываются — эту задачу калькулятор не решает.';
out(h+row('Сравнение с целью',fx(R,rt)+' Ом — '+cmp)+
row('Статус',st)+
note(n));
}
''',
about="""<div class="formula">R = ρ / (2π·L) · [ln(2L/d) + ½·ln((4T + L) / (4T − L))]&nbsp;&nbsp;&nbsp;T = t₀ + L/2<br>Стержень от поверхности (Дуайт, BS 7430): R = ρ / (2π·L) · [ln(8L/d) − 1]</div>
<p>ρ — удельное сопротивление грунта, Ом·м; L — длина электрода, м; d — диаметр или эквивалентный диаметр, м; t₀ — заглубление верхнего конца, T — глубина середины электрода, м. Первая формула приведена в методике расчёта заземления «ВОЛЬТ-СПБ» со ссылкой на справочник под редакцией Ю. Г. Барыбина (табл. 7.9) — в записи через десятичные логарифмы с множителем 0,366. То, что T отсчитывается до середины электрода, указано в расчётах ZandZ и видно в типовом примере для уголка: t = 0,7 + 2,5/2 = 1,95 м. Вторая формула — для стержня, забитого от поверхности, в записи BS 7430.</p>
<p><b>Форма сечения.</b> Для трубы и круглого стержня d — наружный диаметр. Для уголка вместо диаметра подставляют ширину полки b с коэффициентом 0,95, для полосы — 0,5·b. Коэффициенты проверены двумерным расчётом эквивалентного радиуса сечения: для уголков 40–75 мм с полкой 4–6 мм получено 0,93–0,946·b — разница с 0,95 меняет сопротивление меньше чем на 0,5 %, а даже для предельно тонкой полки (0,88·b) — примерно на 1,5 %. У полосы толщиной 3–5 мм эквивалентный диаметр 0,6–0,64·b, так что 0,5·b даёт запас.</p>
<p><b>В какую сторону ошибаются формулы.</b> Обе проверены численным расчётом методом моментов с точным ядром трубчатого проводника и зеркальным изображением в однородном полупространстве; сам метод сверен с независимым расчётом, воспроизводящим точные решения для сферы и вытянутого сфероида. Диаметр 8–60 мм, заглубление верха 0–2 м:</p>
<table class="t"><tr><th>Длина L</th><th>Формула с заглублением</th><th>Дуайт, t₀ = 0</th></tr>
<tr><td>1 м</td><td>от +3,8 до +11,7 %</td><td>от +1,0 до +2,1 %</td></tr>
<tr><td>2 м</td><td>от +3,2 до +9,7 %</td><td>от +0,8 до +1,7 %</td></tr>
<tr><td>3 м</td><td>от +3,0 до +8,6 %</td><td>от +0,6 до +1,5 %</td></tr>
<tr><td>5 м</td><td>от +2,7 до +7,3 %</td><td>от +0,5 до +1,2 %</td></tr>
<tr><td>10 м</td><td>от +2,4 до +5,9 %</td><td>от +0,4 до +0,9 %</td></tr></table>
<p>Обе формулы завышают сопротивление — оценка с запасом. Формула с заглублением грубее: она берёт потенциал в середине электрода, где он наибольший, и сильнее ошибается у коротких толстых и глубоко заглублённых электродов. Для стержня от поверхности (t₀ = 0) калькулятор показывает обе формулы и их расхождение — от 2 до 4,2 %; для сравнения с целью берётся более осторожная формула с заглублением. Вне проверенной области — длина меньше 1 или больше 10 м, эквивалентный диаметр вне 8–60 мм, заглубление больше 2 м — калькулятор не считает.</p>
<p><b>Чем отличается от расчёта стержнями.</b> <a href="raschet-zazemleniya.html">Расчёт заземления стержнями</a> использует грубое R ≈ ρ/(n·L) без диаметра и глубины. Для одного электрода калькулятор показывает ρ/L для сравнения: в проверенной области оно отличается от численного расчёта от −23 до +95 %. Группы электродов, коэффициенты использования и соединительная полоса здесь не рассчитываются: поля растекания электродов перекрываются, и сопротивление группы больше, чем R одного, делённое на их число. Полосу отдельно считает страница <a href="gorizontalnyy-zazemlitel.html">горизонтального заземлителя</a>.</p>
<p><b>Сезон и цель.</b> ρ меняется в течение года: по Schneider Electric на глубине около 1 м сопротивление заземлителя в умеренном климате меняется в 1–3 раза между влажной зимой и сухим летом, а промерзание повышает ρ на порядки. МЭК 60364-5-54 требует выбирать тип и глубину заложения заземлителя так, чтобы высыхание и промерзание грунта не увеличивали сопротивление выше требуемого. Поэтому по ρ без сезонной поправки калькулятор не сравнивает оценку с целью окончательно; если оценка выше цели уже при таком ρ, вывод от сезона не зависит. Требуемое значение задаёт проект — например, условие <a href="zazemlenie-tt-uzo.html">RA·IΔn ≤ 50 В в системе TT</a> или <a href="zamykanie-na-zemlyu-it.html">RA·Id ≤ 50 В в системе IT</a>.</p>""",
example="""<p>Стальной стержень диаметром 16 мм и длиной 3 м, верх на дне траншеи глубиной 0,5 м, ρ = 100 Ом·м. T = 0,5 + 3/2 = 2 м; ln(2 · 3 / 0,016) = ln 375 ≈ 5,927; ½·ln((8 + 3) / (8 − 3)) = ½·ln 2,2 ≈ 0,394; R ≈ 100 / (2π · 3) · 6,321 ≈ 5,305 · 6,321 ≈ <b>33,53 Ом</b>. Численный расчёт даёт 31,74 Ом — формула завышает на 5,7 %. Грубая оценка ρ/L — 33,33 Ом.</p>
<p>Уголок 50×50×5 мм длиной 2,5 м, верх на глубине 0,7 м: d = 0,95 · 50 = 47,5 мм, T = 1,95 м, R ≈ 100 / (2π · 2,5) · (ln 105,3 + ½·ln(10,3 / 5,3)) ≈ 6,366 · 4,989 ≈ <b>31,76 Ом</b>; численный расчёт для реального сечения уголка — 29,48 Ом. Тот же стержень 16 мм, забитый от поверхности: формула с заглублением — 34,36 Ом, формула Дуайта — 33,49 Ом, численный расчёт — 33,21 Ом.</p>""",
